import { useState, useEffect } from 'react';
import MockData from './mockData';
import StatCard from './StatCard';
import RevenueChart from './RevenueChart';

export default function App() {
  const [chartData, setChartData] = useState<number[]>([]);

  useEffect(() => {
    // Mock data for 12 months of revenue
    const mockRevenue = MockData.revenueData.map((month) => month.revenue);
    setChartData(mockRevenue);
  }, []);

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-2xl font-bold text-gray-800 mb-6">Dashboard</h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <StatCard label="Revenue" value="$24,500" trend="up" />
          <StatCard label="Users" value="18,420" trend="up" />
          <StatCard label="Orders" value="1,234" trend="down" />
          <StatCard label="Churn" value="2.3%" trend="down" />
        </div>

        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">Monthly Revenue</h2>
          <RevenueChart data={chartData} />
        </div>
      </div>
    </div>
  );
}
```

